'use strict';
/**
 * interior.js - the cabin picture of the Colour tab as a glyph atlas (picture.js draws it): three alpha bitmaps the
 * renderer tints like text, so the lights take any colour without a pixel image.
 *
 *   'A'  the cabin itself, lights off (512 x 242), drawn in one grey-blue
 *   'B'  the upper lights alone: the dash line and the door line (383 x 182)
 *   'C'  the lower lights alone: the footwell, the door handle and the door pocket (383 x 182)
 *
 * A left-hand-drive saloon seen from the passenger's side. The picture is a generated render, not a photograph of
 * a car; the two light bitmaps are its lights cut out by part. 'size' 100 is the scale: a glyph drawn at size s is
 * s / 100 times its pixels.
 */
module.exports = {
    cacheKey: 'ambient-interior-1',
    aspect: 1536 / 727,
    base: { ch: 'A', w: 512 }, upper: { ch: 'B', w: 383 }, lower: { ch: 'C', w: 383 },
    sizes: [{
        size: 100, ascent: 0, descent: 0, atlasW: 768, atlasH: 428,
        glyphs: {"65": [0, 0, 512, 242, 0, 0, 512], "66": [0, 244, 383, 182, 0, 0, 383], "67": [385, 244, 383, 182, 0, 0, 383]},
        alpha: '',
    }],
};
